def eprint(s):
    sys.stderr.write(s + "\n")

def parse_int_value(value, flagname):
    try:
        # Go's strconv.ParseInt base 10 accepts leading sign, not decimals.
        if not re.fullmatch(r'[+-]?\d+', value):
            raise ValueError
        return int(value, 10)
    except Exception:
        eprint(f"invalid argument for flag `{flagname}' (expected int): strconv.ParseInt: parsing \"{value}\": invalid syntax")
        sys.exit(1)

def apply_value(opts, name, typ, value, flagname):
    if typ == 'int':
        setattr(opts, name, parse_int_value(value, flagname or ('--'+name.replace('_','-'))))
    elif typ == 'float':
        try:
            setattr(opts, name, float(value))
        except Exception:
            eprint(f"invalid argument for flag `--rate-limit' (expected float): strconv.ParseFloat: parsing \"{value}\": invalid syntax")
            sys.exit(1)
    elif typ == 'str':
        setattr(opts, name, value)
    elif typ == 'list':
        getattr(opts, name).append(value)
    elif typ == 'choice_format':
        if value not in ('text','json','junit'):
            eprint(f"Invalid value `{value}' for option `--format'. Allowed values are: text, json or junit")
            sys.exit(1)
        opts.format = value
    elif typ == 'choice_color':
        if value not in ('auto','always','never'):
            eprint(f"Invalid value `{value}' for option `--color'. Allowed values are: auto, always or never")
            sys.exit(1)
        opts.color = value


def parse_args(argv):
    opts = Opts()
    args = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            args.extend(argv[i+1:]); break
        if a in ('-h','--help'):
            print(HELP.format(prog=os.path.basename(sys.argv[0])))
            sys.exit(0)
        if a == '--version':
            print(VERSION)
            sys.exit(0)
        if a.startswith('--') and len(a) > 2:
            keyval = a[2:]
            if '=' in keyval:
                key, val = keyval.split('=',1)
                has_val = True
            else:
                key, val, has_val = keyval, None, False
            if key in LONG_BOOL:
                if has_val:
                    # go-flags rejects this form, but keep simple: non-empty true.
                    setattr(opts, LONG_BOOL[key], val.lower() not in ('0','false','no'))
                else:
                    setattr(opts, LONG_BOOL[key], True)
                i += 1; continue
            if key in LONG_VALUE:
                if not has_val:
                    i += 1
                    if i >= len(argv):
                        # Some go-flags errors say expected argument; tests generally cover final arity.
                        eprint(f"expected argument for flag `--{key}'")
                        sys.exit(1)
                    val = argv[i]
                name, typ, flagname = LONG_VALUE[key]
                apply_value(opts, name, typ, val, flagname)
                i += 1; continue
            eprint(f"unknown flag `{key}'")
            sys.exit(1)
        if a.startswith('-') and a != '-':
            # Handle the short option forms used by the original help.  For options
            # needing a value, both '-t 1' and '-t1' are accepted.
            s = a[1:]
            pos = 0
            while pos < len(s):
                ch = s[pos]
                if ch not in SHORTS:
                    eprint(f"unknown flag `{ch}'")
                    sys.exit(1)
                name, typ, flagname = SHORTS[ch]
                if name == 'help':
                    print(HELP.format(prog=os.path.basename(sys.argv[0])))
                    sys.exit(0)
                if typ == 'bool':
                    setattr(opts, name, True)
                    pos += 1
                    continue
                # Value option: original parser does not use rest of cluster as value
                # for multi-value regexes reliably; accepting it helps common '-t10'.
                if pos + 1 < len(s):
                    val = s[pos+1:]
                    pos = len(s)
                else:
                    i += 1
                    if i >= len(argv):
                        eprint(f"expected argument for flag `{flagname}'")
                        sys.exit(1)
                    val = argv[i]
                    pos = len(s)
                apply_value(opts, name, typ, val, flagname)
            i += 1; continue
        args.append(a)
        i += 1
    if len(args) != 1:
        eprint("invalid number of arguments")
        sys.exit(1)
    # Deprecated switches.  --json and --junit override the default textual format.
    if opts.json_flag:
        opts.format = 'json'
        if opts.experimental_verbose_json:
            opts.verbose = True
    if opts.junit:
        opts.format = 'junit'
    # Compile regexes and headers now, after arity has matched original behavior.
    try:
        opts.compiled_exclude = [re.compile(p) for p in opts.exclude]
        opts.compiled_include = [re.compile(p) for p in opts.include]
    except re.error as ex:
        pat = ''
        # Find first failing pattern for friendlier Go-like message.
        for p in opts.exclude + opts.include:
            try: re.compile(p)
            except re.error: pat = p; break
        if pat == '[':
            eprint("error parsing regexp: missing closing ]: `['")
        else:
            eprint("error parsing regexp: " + str(ex))
        sys.exit(1)
    opts.accepted = parse_status_codes(opts.accepted_status_codes)
    for h in opts.headers:
        if ':' not in h:
            eprint("invalid header format"); sys.exit(1)
        k,v = h.split(':',1)
        if not k.strip():
            eprint("invalid header format"); sys.exit(1)
        opts.header_map[k.strip()] = v.strip()
    return opts, args[0]


def parse_status_codes(s):
    ranges = []
    for part in s.split(','):
        part = part.strip()
        if not part:
            continue
        if '..' in part:
            a,b = part.split('..',1)
            try:
                start = int(a)
            except Exception:
                eprint(f"invalid status code: {a}"); sys.exit(1)
            try:
                end = int(b)
            except Exception:
                eprint(f"invalid status code: {b}"); sys.exit(1)
            ranges.append((start,end))
        else:
            try:
                code = int(part)
            except Exception:
                eprint(f"invalid status code range: {part}"); sys.exit(1)
            ranges.append((code,code+1))
    return ranges

def status_ok(opts, code):
    return any(a <= code < b for a,b in opts.accepted)

def is_html(headers):
    ct = ''
    for k,v in headers.items():
        if k.lower() == 'content-type': ct = v.lower(); break
    return ('text/html' in ct) or ('application/xhtml+xml' in ct)


def default_port(scheme):
    return 443 if scheme == 'https' else 80

def hostport(parts):
    host = parts.hostname or ''
    port = parts.port or default_port(parts.scheme)
    # IPv6 address formatting.
    if ':' in host and not host.startswith('['):
        return f'[{host}]:{port}'
    return f'{host}:{port}'

def normalize_url(raw, base=None, strip_fragment=False):
    # urljoin also handles protocol-relative links.
    u = urljoin(base, raw) if base is not None else raw
    p = urlsplit(u)
    scheme = p.scheme.lower()
    netloc = p.netloc
    path = p.path
    query = p.query
    frag = '' if strip_fragment else p.fragment
    if scheme in ('http','https') and netloc and path == '':
        path = '/'
    # Quote path and fragment while preserving already-escaped octets and URL separators.
    path = quote(unquote(path), safe='/%:@&+$,;=~-._')
    frag = quote(unquote(frag), safe='/?%:@&+$,;=~-._')
    return urlunsplit((scheme, netloc, path, query, frag))

def without_fragment(u):
    p = urlsplit(u)
    return urlunsplit((p.scheme,p.netloc,p.path,p.query,''))

def match_path(opts, u):
    path = urlsplit(u).path
    # Original filtering is path-oriented for typical uses.
    if opts.compiled_include and not any(r.search(path) for r in opts.compiled_include):
        return False
    if opts.compiled_exclude and any(r.search(path) for r in opts.compiled_exclude):
        return False
    return True

class LinkHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.ids = set()
        self.base = None
    def handle_starttag(self, tag, attrs):
        self._tag(tag, attrs)
    def handle_startendtag(self, tag, attrs):
        self._tag(tag, attrs)
    def _tag(self, tag, attrs):
        tag = tag.lower()
        d = {k.lower(): (v if v is not None else '') for k,v in attrs if k}
        if 'id' in d: self.ids.add(d['id'])
        if 'name' in d: self.ids.add(d['name'])
        if tag == 'base' and self.base is None and d.get('href'):
            self.base = d.get('href')
            return
        if tag in ('a','area','link') and d.get('href'):
            self.links.append(d['href'])
        elif tag in ('img','script','iframe','frame','track') and d.get('src'):
            self.links.append(d['src'])
        elif tag == 'source':
            if d.get('src'):
                self.links.append(d['src'])
            if d.get('srcset'):
                for x in parse_srcset(d['srcset']):
                    self.links.append(x)

def parse_srcset(s):
    out=[]
    for item in s.split(','):
        item=item.strip()
        if not item: continue
        out.append(item.split()[0])
    return out

def parse_html(body_bytes):
    # The original is liberal; utf-8 with replacement suffices for observed behavior.
    text = body_bytes.decode('utf-8','replace')
    p = LinkHTMLParser()
    try:
        p.feed(text)
    except Exception:
        pass
    return p

class FetchResult:
    def __init__(self, status=None, headers=None, body=b'', final_url=None, error=None):
        self.status=status; self.headers=headers or {}; self.body=body; self.final_url=final_url; self.error=error

class Fetcher:
    def __init__(self, opts):
        self.opts = opts
        self.cache = {}
        self.last_request = 0.0
    def get(self, url):
        # Cache by URL without fragment because fragments are document-local.
        key = without_fragment(url)
        if key in self.cache:
            return self.cache[key]
        attempts = self.opts.max_retries + 1
        res = None
        for _ in range(attempts):
            res = self._get_uncached(key)
            if res.error and ('connection refused' not in res.error):
                # retry network-ish errors; status errors are handled by caller
                pass
            if not res.error:
                break
        self.cache[key] = res
        return res
    def _rate_wait(self):
        if self.opts.rate_limit and self.opts.rate_limit > 0:
            gap = 1.0 / self.opts.rate_limit
            now = time.time()
            wait = self.last_request + gap - now
            if wait > 0: time.sleep(wait)
            self.last_request = time.time()
    def _get_uncached(self, url):
        parts = urlsplit(url)
        if parts.scheme not in ('http','https'):
            return FetchResult(error=unsupported_error(url, parts))
        if not parts.hostname:
            return FetchResult(error='missing port in address')
