        redirects = 0
        while True:
            p = urlsplit(cur)
            hp = hostport(p)
            pathq = (p.path or '/') + (('?' + p.query) if p.query else '')
            headers = dict(self.opts.header_map)
            try:
                self._rate_wait()
                if p.scheme == 'https':
                    context = ssl._create_unverified_context() if self.opts.skip_tls_verification else None
                    conn = http.client.HTTPSConnection(p.hostname, p.port or 443, timeout=self.opts.timeout, context=context)
                else:
                    conn = http.client.HTTPConnection(p.hostname, p.port or 80, timeout=self.opts.timeout)
                conn.request('GET', pathq, headers=headers)
                resp = conn.getresponse()
                status = resp.status
                hdrs = {k:v for k,v in resp.getheaders()}
                # Redirects are followed regardless of accepted status.
                if status in (301,302,303,307,308) and resp.getheader('Location'):
                    # Drain and close.
                    try: resp.read(1024)
                    except Exception: pass
                    conn.close()
                    if redirects >= self.opts.max_redirections:
                        return FetchResult(error='too many redirections', final_url=cur)
                    redirects += 1
                    cur = normalize_url(resp.getheader('Location'), cur, strip_fragment=False)
                    continue
                limit = max(0, self.opts.max_response_body_size)
                body = resp.read(limit + 1)
                if len(body) > limit:
                    body = body[:limit]
                conn.close()
                return FetchResult(status=status, headers=hdrs, body=body, final_url=normalize_url(cur))
            except socket.gaierror:
                return FetchResult(error=dns_error(p.hostname), final_url=cur)
            except ConnectionRefusedError:
                return FetchResult(error=f'error when dialing {hp}: dial tcp {hp}: connect: connection refused', final_url=cur)
            except socket.timeout:
                return FetchResult(error='context deadline exceeded', final_url=cur)
            except ssl.SSLError as ex:
                return FetchResult(error=str(ex), final_url=cur)
            except http.client.RemoteDisconnected:
                return FetchResult(error="the server closed connection before returning the first response byte. Make sure the server returns 'Connection: close' response header before closing the connection", final_url=cur)
            except OSError as ex:
                if getattr(ex, 'errno', None) == errno.ECONNREFUSED:
                    return FetchResult(error=f'error when dialing {hp}: dial tcp {hp}: connect: connection refused', final_url=cur)
                return FetchResult(error=str(ex), final_url=cur)
            except Exception as ex:
                return FetchResult(error=str(ex), final_url=cur)

def resolver_ip():
    try:
        for line in open('/etc/resolv.conf'):
            m = re.match(r'\s*nameserver\s+(\S+)', line)
            if m: return m.group(1)
    except Exception:
        pass
    return '127.0.0.1'

def dns_error(host):
    return f'lookup {host} on {resolver_ip()}:53: no such host'

def unsupported_error(raw, parts):
    if parts.scheme and '://' in raw:
        return f'unsupported protocol "{parts.scheme}". http and https are supported'
    # Match the common URL parser error for numeric host:port without scheme.
    if re.match(r'^\d+\.\d+\.\d+\.\d+:\d+', raw):
        return f'parse "{raw}": first path segment in URL cannot contain colon'
    if parts.scheme and parts.scheme not in ('http','https'):
        return 'missing port in address'
    return 'missing port in address'

class LinkResult:
    def __init__(self, url, status=None, error=None, final_url=None, html=False, body=b'', headers=None):
        self.url=url; self.status=status; self.error=error; self.final_url=final_url; self.html=html; self.body=body; self.headers=headers or {}
class PageResult:
    def __init__(self, url):
        self.url=url; self.links=[]

def same_origin(a,b):
    pa,pb=urlsplit(a),urlsplit(b)
    return pa.scheme == pb.scheme and pa.netloc == pb.netloc

def has_fragment(u):
    return bool(urlsplit(u).fragment)

def fragment_ok(fragment, parser):
    return unquote(fragment) in parser.ids

def check_link(display_url, fetcher, opts):
    fetch_url = without_fragment(display_url) if opts.ignore_fragments else without_fragment(display_url)
    res = fetcher.get(fetch_url)
    if res.error:
        return LinkResult(display_url, error=res.error, final_url=res.final_url)
    if not status_ok(opts, res.status):
        return LinkResult(display_url, error=str(res.status), final_url=res.final_url, status=res.status, headers=res.headers, body=res.body)
    final_doc_url = res.final_url or fetch_url
    html = is_html(res.headers)
    if has_fragment(display_url) and not opts.ignore_fragments:
        frag = urlsplit(display_url).fragment
        if not html:
            return LinkResult(display_url, error=f'id #{frag} not found', final_url=final_doc_url, status=res.status, headers=res.headers, body=res.body)
        parser = parse_html(res.body)
        if not fragment_ok(frag, parser):
            return LinkResult(display_url, error=f'id #{frag} not found', final_url=final_doc_url, status=res.status, html=html, body=res.body, headers=res.headers)
    return LinkResult(display_url, status=res.status, final_url=final_doc_url, html=html, body=res.body, headers=res.headers)

def discover_links(page_url, body):
    parser = parse_html(body)
    base = page_url
    if parser.base:
        base = normalize_url(parser.base, page_url)
    links=[]
    seen=set()
    for raw in parser.links:
        raw = (raw or '').strip()
        if not raw:
            continue
        # Drop browser-only schemes.
        scheme = urlsplit(raw).scheme.lower()
        if scheme in ('mailto','tel','javascript','data','sms','file'):
            continue
        full = normalize_url(raw, base)
        p = urlsplit(full)
        if p.scheme not in ('http','https'):
            continue
        if full not in seen:
            seen.add(full); links.append(full)
    return links

def run(root_raw, opts):
    root_url = normalize_url(root_raw)
    fetcher = Fetcher(opts)
    root_fetch_url = without_fragment(root_url)
    root_res = fetcher.get(root_fetch_url)
    if root_res.error:
        eprint('failed to fetch root page: ' + root_res.error); return None, 1
    if not status_ok(opts, root_res.status):
        eprint('failed to fetch root page: ' + str(root_res.status)); return None, 1
    if not is_html(root_res.headers):
        eprint('root page has invalid content type'); return None, 1
    if has_fragment(root_url) and not opts.ignore_fragments:
        frag = urlsplit(root_url).fragment
        if not fragment_ok(frag, parse_html(root_res.body)):
            eprint(f'failed to fetch root page: id #{frag} not found'); return None, 1
    start_url = root_res.final_url or root_fetch_url
    origin = start_url
    results=[]; result_by_url={}
    queue=[start_url]
    visited=set()
    any_error=False
    while queue:
        page_url=queue.pop(0)
        page_key=without_fragment(page_url)
        if page_key in visited: continue
        visited.add(page_key)
        pres=PageResult(page_key)
        results.append(pres); result_by_url[page_key]=pres
        fres=fetcher.get(page_key)
        if fres.error or not status_ok(opts, fres.status) or not is_html(fres.headers):
            # This can happen for redirected links that looked crawlable earlier.
            continue
        links = discover_links(page_key, fres.body)
        for lu in links:
            if not match_path(opts, lu):
                continue
            lr = check_link(lu, fetcher, opts)
            pres.links.append(lr)
            if lr.error:
                any_error=True
            if opts.one_page_only:
                continue
            # Crawl same-origin HTML pages.  Fragment links crawl their underlying doc.
            target = without_fragment(lr.final_url or lu)
            if lr.error is None and lr.html and same_origin(origin, target):
                if target not in visited and target not in queue:
                    queue.append(target)
    return results, 1 if any_error else 0

def colorize(s, color, opts, kind):
    use = opts.color == 'always' or (opts.color == 'auto' and sys.stdout.isatty())
    if not use: return s
    code = {'page':'33','ok':'32','err':'31'}.get(kind)
    return f'\033[{code}m{s}\033[0m' if code else s

def output_text(results, opts):
    for p in sorted(results, key=lambda x: x.url):
        visible_links = [l for l in sorted(p.links, key=lambda x: x.url) if opts.verbose or l.error]
        if not opts.verbose and not visible_links:
            continue
        print(colorize(p.url, opts.color, opts, 'page'))
        for l in visible_links:
            if l.error:
                left = colorize(l.error, opts.color, opts, 'err')
            else:
                left = colorize(str(l.status), opts.color, opts, 'ok')
            print(f'\t{left}\t{l.url}')

def output_json(results, opts):
    arr=[]
    for p in sorted(results, key=lambda x: x.url):
        links=[]
        for l in sorted(p.links, key=lambda x: x.url):
            if l.error:
                links.append({'url':l.url,'error':l.error})
            elif opts.verbose:
                links.append({'url':l.url,'status':l.status})
        if opts.verbose or links:
            arr.append({'url':p.url,'links':links})
    print(json.dumps(arr, separators=(',',':')))

def output_junit(results, opts):
    print('<?xml version="1.0" encoding="UTF-8"?>')
    print('<testsuites>')
    for p in sorted(results, key=lambda x: x.url):
        links=sorted(p.links, key=lambda x: x.url)
        failures=sum(1 for l in links if l.error)
        name=xml_escape(p.url, quote=True)
        if not links:
            print(f'  <testsuite name="{name}" tests="0" failures="0" skipped="0"></testsuite>')
            continue
        print(f'  <testsuite name="{name}" tests="{len(links)}" failures="{failures}" skipped="0">')
        for l in links:
            lname=xml_escape(l.url, quote=True)
            print(f'    <testcase name="{lname}" classname="{name}">', end='')
            if l.error:
                print()
                msg=xml_escape(l.error, quote=True)
                print(f'      <failure message="{msg}"></failure>')
                print('    </testcase>')
            else:
                print('</testcase>')
        print('  </testsuite>')
    print('</testsuites>')

def main(argv):
    opts, url = parse_args(argv)
    results, code = run(url, opts)
    if results is not None:
        if opts.format == 'json': output_json(results, opts)
        elif opts.format == 'junit': output_junit(results, opts)
        else: output_text(results, opts)
    return code

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
